 grant all privileges on `my\_1`.* to mysqltest_1@localhost with grant option;
 grant create user on *.* to mysqltest_1@localhost;
 create user mysqltest_2@localhost;
@@ -929,3 +922,53 @@ DROP USER mysqltest_u3@localhost;
 DROP USER mysqltest_u4@localhost;
 DROP USER mysqltest_u5@localhost;
 set GLOBAL sql_mode=default;
+# End of 10.1 tests
+#
+# MDEV-37951 SHOW TABLES allows users with only GRANT OPTION privilege to read all table names in the database "mysql"
+#
+create user u@localhost;
+grant grant option on *.* to u@localhost;
+connect con1, localhost, u;
+show grants;
+Grants for u@localhost
+GRANT USAGE ON *.* TO `u`@`localhost` WITH GRANT OPTION
+show tables from mysql;
+ERROR 42000: Access denied for user 'u'@'localhost' to database 'mysql'
+select * from information_schema.tables where table_schema='mysql';
+TABLE_CATALOG	TABLE_SCHEMA	TABLE_NAME	TABLE_TYPE	ENGINE	VERSION	ROW_FORMAT	TABLE_ROWS	AVG_ROW_LENGTH	DATA_LENGTH	MAX_DATA_LENGTH	INDEX_LENGTH	DATA_FREE	AUTO_INCREMENT	CREATE_TIME	UPDATE_TIME	CHECK_TIME	TABLE_COLLATION	CHECKSUM	CREATE_OPTIONS	TABLE_COMMENT	MAX_INDEX_LENGTH	TEMPORARY
+disconnect con1;
+connection default;
+revoke grant option on *.* from u@localhost;
+grant select (host) on mysql.user to u@localhost with grant option;
+revoke select (host) on mysql.user from u@localhost;
+connect con1, localhost, u;
+show grants;
+Grants for u@localhost
+GRANT USAGE ON *.* TO `u`@`localhost`
+GRANT USAGE ON `mysql`.`user` TO `u`@`localhost` WITH GRANT OPTION
+show tables from mysql;
+Tables_in_mysql
+user
+select * from information_schema.tables where table_schema='mysql';
+TABLE_CATALOG	TABLE_SCHEMA	TABLE_NAME	TABLE_TYPE	ENGINE	VERSION	ROW_FORMAT	TABLE_ROWS	AVG_ROW_LENGTH	DATA_LENGTH	MAX_DATA_LENGTH	INDEX_LENGTH	DATA_FREE	AUTO_INCREMENT	CREATE_TIME	UPDATE_TIME	CHECK_TIME	TABLE_COLLATION	CHECKSUM	CREATE_OPTIONS	TABLE_COMMENT	MAX_INDEX_LENGTH	TEMPORARY
+def	mysql	user	VIEW	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	NULL	VIEW	NULL	NULL
+disconnect con1;
+connection default;
+revoke grant option on mysql.user from u@localhost;
+create procedure mysql.p1() select 1;
+grant execute on procedure mysql.p1 to u@localhost with grant option;
+revoke execute on procedure mysql.p1 from u@localhost;
+connect con1, localhost, u;
+show grants;
+Grants for u@localhost
+GRANT USAGE ON *.* TO `u`@`localhost`
+GRANT USAGE ON PROCEDURE `mysql`.`p1` TO `u`@`localhost` WITH GRANT OPTION
+show tables from mysql;
+Tables_in_mysql
+select * from information_schema.tables where table_schema='mysql';
+TABLE_CATALOG	TABLE_SCHEMA	TABLE_NAME	TABLE_TYPE	ENGINE	VERSION	ROW_FORMAT	TABLE_ROWS	AVG_ROW_LENGTH	DATA_LENGTH	MAX_DATA_LENGTH	INDEX_LENGTH	DATA_FREE	AUTO_INCREMENT	CREATE_TIME	UPDATE_TIME	CHECK_TIME	TABLE_COLLATION	CHECKSUM	CREATE_OPTIONS	TABLE_COMMENT	MAX_INDEX_LENGTH	TEMPORARY
+disconnect con1;
+connection default;
+drop procedure mysql.p1;
+drop user u@localhost;
+# End of 10.11 tests
